//! Tests of stamp signing, the registry rules and the keystore (GitHub
//! #762). Every key is generated by [`keystore::generate`] (real argon2id +
//! AES-256-GCM + ed25519, no mocks), and every stamp is signed over the real
//! [`signed_bytes`].
//!
//! Methodology, for every test below: build a `kovan_root.toml` registry in
//! memory ([`ReviewRoot`]) from generated keys, sign entries with
//! [`keystore::UnlockedKey`], then judge them with [`Registry::build`] and
//! [`verify_review`] / [`verify_architecture`]. Pass criterion: the exact
//! typed [`SignatureCheck`] / [`KeyStatus`] / [`Warning`] the rule in the
//! module docs predicts.
//!
//! Result (2026-10-07): all pass (`cargo test --release -j 1 -p kovan-common
//! --lib --tests`).

use std::collections::BTreeMap;

use super::keystore::{self, KeyFile, Keystore, KeystoreError, SignError, UnlockedKey};
use super::registry::{
    Admission, AdmissionProblem, FounderProblem, KeyProblem, KeyStatus,
    LifecycleError, Registry, RevocationProblem, SignerProblem, Warning,
};
use super::*;
use crate::review::review_md::{ArchitectureBody, EntryMeta, ReviewBody};
use crate::review::root::{
    KeyEvent, KeyEventKind, KeySigner, ReviewRoot, Reviewer, ReviewerKey, Revocation, Role,
};

pub(super) const SHA: &str = "0123456789abcdef0123456789abcdef01234567";
pub(super) const PASS: &str = "correct horse battery staple";
pub(super) const FOUNDER: &str = "github:founder";
pub(super) const ALICE: &str = "alice@example.org";

pub(super) fn h(c: char) -> String {
    format!("sha256:{}", c.to_string().repeat(64))
}

pub(super) fn review_entry(function: &str, by: &str, date: &str) -> ReviewEntry {
    ReviewEntry {
        kovan: EntryMeta {
            id: "review-f".into(),
            kind: "review".into(),
            origin: Some("human".into()),
            created: "2026-10-07T10:00:00+08:00".into(),
            modified: "2026-10-07T10:00:00+08:00".into(),
            target: Some(crate::review::id::mint_fn_id(function, &h('a'), SHA)),
        },
        review: ReviewBody {
            path: Some(function.into()),
            by: by.into(),
            rung: 3,
            date: date.into(),
            signed_at: None,
            commit: SHA.into(),
            hash: h('a'),
            doc_hash: h('b'),
            cargo_lock: Some(h('c')),
            callees: BTreeMap::new(),
            checklist: BTreeMap::from([("q1".to_string(), "yes".to_string())]),
            no_concept: None,
            authorship: None,
            moved: vec![],
            separation_attestation: None,
            signature: None,
        },
        relations: vec![],
    }
}

pub(super) fn signed(k: &UnlockedKey, function: &str, date: &str) -> ReviewEntry {
    let mut r = review_entry(function, k.reviewer(), date);
    k.sign_review(&mut r).unwrap();
    r
}

/// A fresh key for `reviewer`: its registry entry and the unlocked key.
pub(super) fn key(reviewer: &str, id: &str) -> (ReviewerKey, UnlockedKey) {
    let (file, unlocked) = keystore::generate(reviewer, id, "2026-10-07", PASS).unwrap();
    (file.reviewer_key(), unlocked)
}

pub(super) fn person(id: &str, role: Role, keys: Vec<ReviewerKey>) -> Reviewer {
    Reviewer {
        id: id.into(),
        name: None,
        role,
        scope: vec![],
        qualification: vec![],
        admitted: None,
        admitted_by: None,
        keys,
        revoked: None,
        organisations: vec![],
        separations: vec![],
    }
}

/// A registry whose `[code_review] founder` is [`FOUNDER`].
pub(super) fn root(reviewers: Vec<Reviewer>) -> ReviewRoot {
    root_with_founder(Some(FOUNDER), reviewers)
}

pub(super) fn root_with_founder(founder: Option<&str>, reviewers: Vec<Reviewer>) -> ReviewRoot {
    ReviewRoot {
        code_review: Some(crate::review::root::CodeReviewSettings {
            rust_analyzer: None,
            founder: founder.map(str::to_string),
            rust_analyzer_used: vec![],
            developing_organisation: vec![],
        }),
        reviewers,
        deleted_crates: vec![],
    }
}

/// The founder (key `k1`) plus Alice, a reviewer scoped to
/// `crates/tampines/**`, admitted by the founder (key `a1`).
pub(super) fn founder_and_alice() -> (Reviewer, UnlockedKey, Reviewer, UnlockedKey) {
    let (fk, f) = key(FOUNDER, "k1");
    let founder = person(FOUNDER, Role::Maintainer, vec![fk]);
    let (ak, a) = key(ALICE, "a1");
    let mut alice = person(ALICE, Role::Reviewer, vec![ak]);
    alice.scope = vec!["crates/tampines/**".into()];
    alice.admitted = Some("2026-10-07".into());
    f.admit(&mut alice).unwrap();
    (founder, f, alice, a)
}

pub(super) fn unverified(c: SignatureCheck) -> UnverifiedReason {
    match c {
        SignatureCheck::Unverified(u) => u,
        SignatureCheck::Verified(v) => panic!("expected unverified, got {v:?}"),
    }
}

pub(super) const F: &str = "crates/tampines/src/steam.rs::flash";

/// Round trip over the real signed bytes: the founder's first key is
/// trusted on first use and its signed review verifies. Fields that are not
/// signed (artifact id, timestamps) may change; signed ones may not.
#[test]
fn sign_verify_round_trip_and_tamper() {
    let (fk, f) = key(FOUNDER, "k1");
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![fk])]));
    assert_eq!(reg.founder, Ok(FOUNDER.to_string()));
    assert!(reg.warnings().is_empty());
    let r = signed(&f, F, "2026-10-07");
    let SignatureCheck::Verified(v) = verify_review(&r, &reg) else { panic!() };
    assert_eq!(v.reviewer, FOUNDER);
    assert_eq!(v.key, "k1");
    assert_eq!(v.key_status, KeyStatus::TrustedOnFirstUse);
    assert!(!v.reset);
    assert!(verify_review(&r, &reg).is_verified());

    let mut same = r.clone();
    same.kovan.id = "renamed".into();
    same.kovan.modified = "2026-10-08T00:00:00+08:00".into();
    assert!(verify_review(&same, &reg).is_verified());

    // An agent edits code and copies the new hash in without re-signing (D6).
    let mut t = r.clone();
    t.review.hash = h('e');
    assert_eq!(unverified(verify_review(&t, &reg)), UnverifiedReason::BadSignature);
    let mut t = r.clone();
    t.review.commit = "fedcba9876543210fedcba9876543210fedcba98".into();
    assert_eq!(unverified(verify_review(&t, &reg)), UnverifiedReason::BadSignature);
    let mut t = r.clone();
    t.review.checklist.insert("q1".into(), "no".into());
    assert_eq!(unverified(verify_review(&t, &reg)), UnverifiedReason::BadSignature);
    let mut t = r.clone();
    t.review.date = "2026-10-06".into();
    assert_eq!(unverified(verify_review(&t, &reg)), UnverifiedReason::BadSignature);
}

/// Another secret key under the same reviewer and key id: the signature is
/// well formed but does not verify with the registered public key.
#[test]
fn wrong_key_fails() {
    let (fk, _f) = key(FOUNDER, "k1");
    let (_other_entry, other) = key(FOUNDER, "k1");
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![fk])]));
    let r = signed(&other, F, "2026-10-07");
    assert_eq!(unverified(verify_review(&r, &reg)), UnverifiedReason::BadSignature);
}

/// Every early "no" of the stamp check, in order.
#[test]
fn stamp_check_refusals() {
    let (fk, f) = key(FOUNDER, "k1");
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![fk])]));
    let bare = review_entry(F, FOUNDER, "2026-10-07");
    assert_eq!(unverified(verify_review(&bare, &reg)), UnverifiedReason::NoSignature);

    let r = signed(&f, F, "2026-10-07");
    let mut t = r.clone();
    t.review.signature.as_mut().unwrap().alg = "rsa".into();
    assert_eq!(
        unverified(verify_review(&t, &reg)),
        UnverifiedReason::UnsupportedAlgorithm("rsa".into())
    );
    let mut t = r.clone();
    t.review.signature.as_mut().unwrap().key = "k9".into();
    assert!(matches!(unverified(verify_review(&t, &reg)), UnverifiedReason::UnknownKey { .. }));
    let mut t = r.clone();
    t.review.signature.as_mut().unwrap().value = "not base64!".into();
    assert_eq!(
        unverified(verify_review(&t, &reg)),
        UnverifiedReason::Malformed(CryptoError::BadBase64 { field: "signature" })
    );
    let mut t = r.clone();
    t.review.signature.as_mut().unwrap().value = encode_b64(&[0u8; 10]);
    assert_eq!(
        unverified(verify_review(&t, &reg)),
        UnverifiedReason::Malformed(CryptoError::BadLength { field: "signature", len: 10 })
    );

    let (_, stranger) = key(ALICE, "a1");
    let s = signed(&stranger, F, "2026-10-07");
    assert_eq!(unverified(verify_review(&s, &reg)), UnverifiedReason::UnknownReviewer(ALICE.into()));

    let bad_date = signed(&f, F, "7 Oct 2026");
    assert_eq!(unverified(verify_review(&bad_date, &reg)), UnverifiedReason::BadDate("7 Oct 2026".into()));
}

/// Keystore round trip: save (never overwrite), list, load, unlock with the
/// passphrase; a wrong passphrase, an edited header and an empty passphrase
/// are typed errors.
#[test]
fn keystore_round_trip_and_wrong_passphrase() {
    let dir = tempfile::tempdir().unwrap();
    let ks = Keystore::at(dir.path().join("keys"));
    assert_eq!(ks.dir(), dir.path().join("keys"));
    assert_eq!(ks.list().unwrap(), vec![]);
    let (file, unlocked) = keystore::generate(FOUNDER, "k1", "2026-10-07", PASS).unwrap();
    let path = ks.save(&file).unwrap();
    assert_eq!(path, ks.path_for(FOUNDER, "k1"));
    assert!(path.file_name().unwrap().to_str().unwrap().ends_with("--k1.kovankey"));
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        assert_eq!(std::fs::metadata(&path).unwrap().permissions().mode() & 0o777, 0o600);
    }
    // Nothing secret in the clear.
    let text = std::fs::read_to_string(&path).unwrap();
    assert!(!text.contains(PASS));
    assert!(matches!(ks.save(&file), Err(KeystoreError::AlreadyExists(_))));
    assert_eq!(ks.list().unwrap(), vec![file.clone()]);

    let loaded = ks.load(FOUNDER, "k1").unwrap();
    assert_eq!(loaded, file);
    let again = loaded.unlock(PASS).unwrap();
    assert_eq!(again.public_b64(), unlocked.public_b64());
    assert_eq!(again.public_b64(), file.public);
    assert_eq!((again.reviewer(), again.key_id()), (FOUNDER, "k1"));
    assert!(!format!("{again:?}").contains(&file.cipher.ciphertext));
    assert!(format!("{again:?}").contains("<secret>"));
    // The re-unlocked key signs stamps the registry accepts.
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![file.reviewer_key()])]));
    assert!(verify_review(&signed(&again, F, "2026-10-07"), &reg).is_verified());

    assert_eq!(loaded.unlock("wrong passphrase").unwrap_err(), KeystoreError::WrongPassphrase);
    assert_eq!(loaded.unlock("").unwrap_err(), KeystoreError::EmptyPassphrase);
    let mut edited = loaded.clone();
    edited.created = "2026-10-08".into();
    assert_eq!(edited.unlock(PASS).unwrap_err(), KeystoreError::WrongPassphrase);
    // A swapped public key with the header re-bound can only come from
    // someone re-encrypting; the decrypted seed then no longer matches.
    let (other, _) = keystore::generate(FOUNDER, "k1", "2026-10-07", PASS).unwrap();
    let mut swapped = other.clone();
    swapped.public = file.public.clone();
    assert_eq!(swapped.unlock(PASS).unwrap_err(), KeystoreError::WrongPassphrase);
    let sealed = keystore::seal(FOUNDER, "k1", "2026-10-07", &file.public, &[9u8; 32], PASS).unwrap();
    assert_eq!(sealed.unlock(PASS).unwrap_err(), KeystoreError::KeyMismatch);

    std::fs::write(ks.path_for(ALICE, "a1"), file.to_toml().unwrap()).unwrap();
    assert!(matches!(ks.load(ALICE, "a1"), Err(KeystoreError::WrongFile { .. })));
    std::fs::write(dir.path().join("keys/junk.kovankey"), "not toml [").unwrap();
    assert!(matches!(ks.list(), Err(KeystoreError::Parse { path: Some(_), .. })));
    assert!(matches!(ks.load("github:nobody", "k1"), Err(KeystoreError::Io { .. })));
}

/// Generation refuses bad inputs; unlocking refuses files it does not
/// understand or that ask for too much memory.
#[test]
fn keystore_refusals() {
    assert_eq!(keystore::generate(FOUNDER, "k1", "2026-10-07", "").unwrap_err(), KeystoreError::EmptyPassphrase);
    assert!(matches!(keystore::generate("Theodore", "k1", "2026-10-07", PASS), Err(KeystoreError::Field(_))));
    assert_eq!(
        keystore::generate(FOUNDER, "../k", "2026-10-07", PASS).unwrap_err(),
        KeystoreError::BadKeyId("../k".into())
    );
    assert_eq!(
        keystore::generate(FOUNDER, "k1", "today", PASS).unwrap_err(),
        KeystoreError::BadDate("today".into())
    );
    let (file, _) = keystore::generate(FOUNDER, "k1", "2026-10-07", PASS).unwrap();
    let mut f = file.clone();
    f.format = "v0".into();
    assert!(matches!(f.unlock(PASS), Err(KeystoreError::Unsupported(_))));
    let mut f = file.clone();
    f.cipher.alg = "chacha".into();
    assert!(matches!(f.unlock(PASS), Err(KeystoreError::Unsupported(_))));
    let mut f = file.clone();
    f.kdf.alg = "scrypt".into();
    assert!(matches!(f.unlock(PASS), Err(KeystoreError::Unsupported(_))));
    let mut f = file.clone();
    f.kdf.m_cost = keystore::ARGON2_M_COST_MAX + 1;
    assert!(matches!(f.unlock(PASS), Err(KeystoreError::Kdf(_))));
    let mut f = file.clone();
    f.kdf.t_cost = 0;
    assert!(matches!(f.unlock(PASS), Err(KeystoreError::Kdf(_))));
    let mut f = file.clone();
    f.kdf.salt = "x".into();
    assert_eq!(f.unlock(PASS).unwrap_err(), KeystoreError::BadField("kdf.salt".into()));
    let mut f = file.clone();
    f.cipher.nonce = "AAAA".into();
    assert_eq!(f.unlock(PASS).unwrap_err(), KeystoreError::BadField("cipher.nonce".into()));
    let mut f = file.clone();
    f.cipher.ciphertext = "!!".into();
    assert_eq!(f.unlock(PASS).unwrap_err(), KeystoreError::BadField("cipher.ciphertext".into()));
    assert!(matches!(KeyFile::from_toml("format = 1"), Err(KeystoreError::Parse { path: None, .. })));
    assert_eq!(KeyFile::from_toml(&file.to_toml().unwrap()).unwrap(), file);
    // The default location is kovan's config folder; nothing is created.
    if let Ok(ks) = Keystore::default_location() {
        assert!(ks.dir().ends_with("keys"));
    }
}

/// Endorsement chain: k1 (founder, trusted on first use) -> k2 -> k3 all
/// trusted; a tampered endorsement, an unknown endorser and a cycle are not.
#[test]
fn endorsement_chain_valid_and_invalid() {
    let (k1, u1) = key(FOUNDER, "k1");
    let (mut k2, u2) = key(FOUNDER, "k2");
    let (mut k3, u3) = key(FOUNDER, "k3");
    u1.endorse(FOUNDER, &mut k2, "2026-10-07").unwrap();
    u2.endorse(FOUNDER, &mut k3, "2026-10-07").unwrap();
    // List order does not matter (fixed point): k3 before k2.
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![k1.clone(), k3.clone(), k2.clone()])]));
    let r = reg.reviewer(FOUNDER).unwrap();
    assert_eq!(r.admission, Admission::Founder);
    assert_eq!(r.key("k2").unwrap().status, KeyStatus::Endorsed { by_reviewer: FOUNDER.into(), by_key: "k1".into() });
    assert_eq!(r.key("k3").unwrap().status, KeyStatus::Endorsed { by_reviewer: FOUNDER.into(), by_key: "k2".into() });
    assert!(verify_review(&signed(&u3, F, "2026-10-07"), &reg).is_verified());

    let mut bad2 = k2.clone();
    bad2.created = "2026-10-08".into();
    let (mut k4, _) = key(FOUNDER, "k4");
    k4.history.push(KeyEvent {
        event: KeyEventKind::Endorsed,
        date: "2026-10-07".into(),
        signer: Some(KeySigner { reviewer: None, key: "k9".into() }),
        signature: Some("AAAA".into()),
        legacy: false,
    });
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![k1.clone(), bad2, k3.clone(), k4])]));
    let r = reg.reviewer(FOUNDER).unwrap();
    assert_eq!(r.key("k2").unwrap().status, KeyStatus::Untrusted(KeyProblem::Endorsement(SignerProblem::BadSignature)));
    // k3 hangs off the broken k2.
    assert_eq!(
        r.key("k3").unwrap().status,
        KeyStatus::Untrusted(KeyProblem::Endorsement(SignerProblem::NotTrusted { key: "k2".into() }))
    );
    assert_eq!(
        r.key("k4").unwrap().status,
        KeyStatus::Untrusted(KeyProblem::Endorsement(SignerProblem::UnknownKey { key: "k9".into() }))
    );
    assert_eq!(
        unverified(verify_review(&signed(&u3, F, "2026-10-07"), &reg)),
        UnverifiedReason::KeyNotTrusted {
            reviewer: FOUNDER.into(),
            key: "k3".into(),
            problem: KeyProblem::Endorsement(SignerProblem::NotTrusted { key: "k2".into() }),
        }
    );

    // A cycle (k5 endorses k6, k6 endorses k5) never becomes trusted.
    let (mut k5, u5) = key(FOUNDER, "k5");
    let (mut k6, u6) = key(FOUNDER, "k6");
    u5.endorse(FOUNDER, &mut k6, "2026-10-07").unwrap();
    u6.endorse(FOUNDER, &mut k5, "2026-10-07").unwrap();
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![k1, k5, k6])]));
    let r = reg.reviewer(FOUNDER).unwrap();
    assert!(!r.key("k5").unwrap().status.is_trusted());
    assert!(!r.key("k6").unwrap().status.is_trusted());
}

/// An unendorsed key: a loud warning, and its signatures do not count.
#[test]
fn unendorsed_key_is_loud_and_does_not_count() {
    let (k1, _) = key(FOUNDER, "k1");
    let (k2, u2) = key(FOUNDER, "k2");
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![k1, k2])]));
    assert_eq!(
        reg.warnings(),
        vec![Warning::KeyNotTrusted { reviewer: FOUNDER.into(), key: "k2".into(), problem: KeyProblem::Unendorsed }]
    );
    let r = signed(&u2, F, "2026-10-07");
    assert!(matches!(
        unverified(verify_review(&r, &reg)),
        UnverifiedReason::KeyNotTrusted { problem: KeyProblem::Unendorsed, .. }
    ));
}

/// Resets: the founder may reset without an endorsement, a reviewer needs a
/// maintainer's; either way the reset shows in the warnings and on every
/// verified stamp.
#[test]
fn reset_is_permanently_visible() {
    let (k1, _lost) = key(FOUNDER, "k1");
    let (mut k2, u2) = key(FOUNDER, "k2");
    k2.history.push(KeyEvent::unsigned(KeyEventKind::Reset, "2026-10-07"));
    // Founder reset, no endorsement.
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![k1, k2.clone()])]));
    let st = reg.reviewer(FOUNDER).unwrap().key("k2").unwrap().status.clone();
    assert_eq!(st, KeyStatus::ResetTrustedOnFirstUse);
    assert_eq!(
        reg.warnings(),
        vec![Warning::KeyReset { reviewer: FOUNDER.into(), key: "k2".into(), status: st.clone() }]
    );
    let SignatureCheck::Verified(v) = verify_review(&signed(&u2, F, "2026-10-07"), &reg) else { panic!() };
    assert!(v.reset);
    assert_eq!(v.key_status, KeyStatus::ResetTrustedOnFirstUse);

    // Alice resets: without an endorsement it does not count; with the
    // founder's it does, still flagged.
    let (founder, f, mut alice, _a) = founder_and_alice();
    let (mut ar, ua) = key(ALICE, "a2");
    ar.history.push(KeyEvent::unsigned(KeyEventKind::Reset, "2026-10-07"));
    alice.keys.push(ar.clone());
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().key("a2").unwrap().status,
        KeyStatus::Untrusted(KeyProblem::Unendorsed)
    );
    // The unsigned reset entry stays (append-only); the maintainer's signed
    // one is appended after it and is what makes the key trusted.
    f.endorse_reset(ALICE, alice.keys.last_mut().unwrap(), "2026-10-07").unwrap();
    let reg = Registry::build(&root(vec![founder, alice]));
    let st = reg.reviewer(ALICE).unwrap().key("a2").unwrap().status.clone();
    assert_eq!(st, KeyStatus::Endorsed { by_reviewer: FOUNDER.into(), by_key: "k1".into() });
    assert!(reg.warnings().contains(&Warning::KeyReset { reviewer: ALICE.into(), key: "a2".into(), status: st }));
    let SignatureCheck::Verified(v) = verify_review(&signed(&ua, F, "2026-10-08"), &reg) else { panic!() };
    assert!(v.reset);
}

/// One maintainer's signature admits a reviewer; the admission covers the
/// scope and the first key, so widening the scope breaks it. A stamp
/// outside scope does not count; a maintainer has no scope limit.
#[test]
fn admission_and_scope() {
    let (founder, f, alice, a) = founder_and_alice();
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    let r = reg.reviewer(ALICE).unwrap();
    assert_eq!(r.admission, Admission::Admitted { by: FOUNDER.into(), key: "k1".into() });
    assert_eq!(r.key("a1").unwrap().status, KeyStatus::Admitted);
    assert!(verify_review(&signed(&a, F, "2026-10-08"), &reg).is_verified());
    assert_eq!(
        unverified(verify_review(&signed(&a, "crates/njoy/src/a.rs::g", "2026-10-08"), &reg)),
        UnverifiedReason::OutsideScope { reviewer: ALICE.into(), path: "crates/njoy/src/a.rs".into() }
    );
    // The founder stamps anywhere.
    assert!(verify_review(&signed(&f, "crates/njoy/src/a.rs::g", "2026-10-08"), &reg).is_verified());

    // Widening the scope without a new admission.
    let mut wide = alice.clone();
    wide.scope = vec!["crates/**".into()];
    let reg = Registry::build(&root(vec![founder.clone(), wide]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().admission,
        Admission::NotAdmitted(AdmissionProblem::Signer(SignerProblem::BadSignature))
    );
    assert_eq!(
        unverified(verify_review(&signed(&a, F, "2026-10-08"), &reg)),
        UnverifiedReason::ReviewerNotAdmitted {
            reviewer: ALICE.into(),
            problem: AdmissionProblem::Signer(SignerProblem::BadSignature),
        }
    );

    // Not admitted at all; undated; bad date; keyless.
    let mut none = alice.clone();
    none.keys[0].history.retain(|e| e.event != KeyEventKind::Admitted);
    let mut undated = alice.clone();
    undated.admitted = None;
    let mut bad = alice.clone();
    bad.admitted = Some("soon".into());
    let mut keyless = alice.clone();
    keyless.keys.clear();
    for (who, want) in [
        (none, AdmissionProblem::Unadmitted),
        (undated, AdmissionProblem::Undated),
        (bad, AdmissionProblem::BadDate("soon".into())),
        (keyless, AdmissionProblem::NoKey),
    ] {
        let reg = Registry::build(&root(vec![founder.clone(), who]));
        assert_eq!(reg.reviewer(ALICE).unwrap().admission, Admission::NotAdmitted(want.clone()));
        assert!(reg
            .warnings()
            .contains(&Warning::ReviewerNotAdmitted { reviewer: ALICE.into(), problem: want }));
    }

    // A reviewer (not a maintainer) cannot admit anyone.
    let bob_id = "github:bob";
    let (bk, _b) = key(bob_id, "b1");
    let mut bob = person(bob_id, Role::Reviewer, vec![bk]);
    bob.admitted = Some("2026-10-08".into());
    a.admit(&mut bob).unwrap();
    let reg = Registry::build(&root(vec![founder, alice, bob]));
    assert_eq!(
        reg.reviewer(bob_id).unwrap().admission,
        Admission::NotAdmitted(AdmissionProblem::Signer(SignerProblem::NotEligible(ALICE.into())))
    );
    assert_eq!(
        reg.reviewer(bob_id).unwrap().key("b1").unwrap().status,
        KeyStatus::Untrusted(KeyProblem::ReviewerNotAdmitted)
    );
}

/// A maintainer admitted by the founder can admit others (the chain), but
/// not after their own revocation.
#[test]
fn admission_chain_and_revoked_admitter() {
    let (fk, f) = key(FOUNDER, "k1");
    let founder = person(FOUNDER, Role::Maintainer, vec![fk]);
    let m2_id = "github:second";
    let (mk, m) = key(m2_id, "m1");
    let mut m2 = person(m2_id, Role::Maintainer, vec![mk]);
    m2.admitted = Some("2026-10-07".into());
    f.admit(&mut m2).unwrap();
    let (ak, _a) = key(ALICE, "a1");
    let mut alice = person(ALICE, Role::Reviewer, vec![ak]);
    alice.admitted = Some("2026-12-05".into());
    m.admit(&mut alice).unwrap();
    // Alice listed before her admitter: the fixed point still admits her.
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone(), m2.clone()]));
    assert_eq!(reg.reviewer(ALICE).unwrap().admission, Admission::Admitted { by: m2_id.into(), key: "m1".into() });

    m2.revoked = Some(Revocation { date: "2026-12-01".into(), compromised_from: None, by: FOUNDER.into(), signature: None });
    f.revoke(m2_id, m2.revoked.as_mut().unwrap()).unwrap();
    let reg = Registry::build(&root(vec![founder, alice, m2]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().admission,
        Admission::NotAdmitted(AdmissionProblem::Signer(SignerProblem::SignerRevoked {
            signer: m2_id.into(),
            date: "2026-12-01".into()
        }))
    );
}

/// Revocation: stamps before the date stay valid; for a compromised key,
/// stamps from the compromise date are void. An unsigned revocation is
/// still honoured, and listed as a warning.
#[test]
fn revocation_before_after_and_compromised() {
    let (founder, f, mut alice, a) = founder_and_alice();
    alice.revoked = Some(Revocation { date: "2026-12-01".into(), compromised_from: None, by: FOUNDER.into(), signature: None });
    // Unsigned first: honoured, loud.
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    assert!(reg.warnings().contains(&Warning::RevocationUnverified {
        reviewer: ALICE.into(),
        problem: RevocationProblem::Signer(SignerProblem::Unsigned)
    }));
    assert_eq!(
        unverified(verify_review(&signed(&a, F, "2026-12-01"), &reg)),
        UnverifiedReason::Revoked { date: "2026-12-01".into() }
    );

    f.revoke(ALICE, alice.revoked.as_mut().unwrap()).unwrap();
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    assert_eq!(reg.reviewer(ALICE).unwrap().revocation.as_ref().unwrap().signed, Ok("k1".into()));
    assert!(reg.warnings().is_empty());
    assert!(verify_review(&signed(&a, F, "2026-11-30"), &reg).is_verified());
    assert_eq!(
        unverified(verify_review(&signed(&a, F, "2026-12-02"), &reg)),
        UnverifiedReason::Revoked { date: "2026-12-01".into() }
    );

    let rv = alice.revoked.as_mut().unwrap();
    rv.compromised_from = Some("2026-11-20".into());
    // The old signature no longer covers the edited revocation.
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().revocation.as_ref().unwrap().signed,
        Err(RevocationProblem::Signer(SignerProblem::BadSignature))
    );
    f.revoke(ALICE, alice.revoked.as_mut().unwrap()).unwrap();
    let reg = Registry::build(&root(vec![founder.clone(), alice.clone()]));
    assert!(verify_review(&signed(&a, F, "2026-11-19"), &reg).is_verified());
    assert_eq!(
        unverified(verify_review(&signed(&a, F, "2026-11-25"), &reg)),
        UnverifiedReason::Compromised { from: "2026-11-20".into() }
    );

    // Only an admitted maintainer can sign a revocation; dates must parse;
    // a maintainer may revoke themselves.
    let mut by_alice = alice.clone();
    by_alice.revoked.as_mut().unwrap().by = ALICE.into();
    let mut bad_date = alice.clone();
    bad_date.revoked.as_mut().unwrap().date = "December".into();
    let reg = Registry::build(&root(vec![founder.clone(), by_alice]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().revocation.as_ref().unwrap().signed,
        Err(RevocationProblem::SignerNotMaintainer(ALICE.into()))
    );
    let reg = Registry::build(&root(vec![founder.clone(), bad_date]));
    assert_eq!(
        reg.reviewer(ALICE).unwrap().revocation.as_ref().unwrap().signed,
        Err(RevocationProblem::BadDate("December".into()))
    );
    // A malformed revocation date voids every stamp (conservative).
    assert!(matches!(
        unverified(verify_review(&signed(&a, F, "2026-01-01"), &reg)),
        UnverifiedReason::Revoked { .. }
    ));
    let mut me = founder.clone();
    me.revoked = Some(Revocation { date: "2027-01-01".into(), compromised_from: None, by: FOUNDER.into(), signature: None });
    f.revoke(FOUNDER, me.revoked.as_mut().unwrap()).unwrap();
    let reg = Registry::build(&root(vec![me]));
    assert_eq!(reg.reviewer(FOUNDER).unwrap().revocation.as_ref().unwrap().signed, Ok("k1".into()));
}

/// No founder, nothing trusted; bad keys are typed.
#[test]
fn founder_and_key_problems() {
    let (ak, _a) = key(ALICE, "a1");

    let mut rsa = ak.clone();
    rsa.alg = "rsa".into();
    let mut junk = ak.clone();
    junk.id = "a2".into();
    junk.public = "AAAA".into();
    let mut undated = ak.clone();
    undated.id = "a3".into();
    undated.created = "now".into();
    let reg = Registry::build(&root(vec![person(FOUNDER, Role::Maintainer, vec![rsa, junk, undated, ak.clone(), ak])]));
    let r = reg.reviewer(FOUNDER).unwrap();
    assert_eq!(r.keys[0].status, KeyStatus::Untrusted(KeyProblem::UnsupportedAlgorithm("rsa".into())));
    assert_eq!(
        r.keys[1].status,
        KeyStatus::Untrusted(KeyProblem::BadPublicKey(CryptoError::BadLength { field: "public key", len: 3 }))
    );
    assert_eq!(r.keys[2].status, KeyStatus::Untrusted(KeyProblem::BadCreatedDate("now".into())));
    assert_eq!(r.keys[4].status, KeyStatus::Untrusted(KeyProblem::DuplicateId));
    // A stamp by a key whose public key does not decode is Malformed.
    let mut fake = review_entry(F, FOUNDER, "2026-10-07");
    fake.review.signature = Some(Signature { key: "a2".into(), alg: ALG.into(), value: encode_b64(&[0; 64]) });
    assert!(matches!(unverified(verify_review(&fake, &reg)), UnverifiedReason::Malformed(_)));
}

/// Architecture nodes are signed like reviews; a reviewer's node must have
/// member paths, all in scope. Members are `fn:` ids and their locations
/// `member_paths` (the first-version paths-as-members form is not read,
/// #825).
#[test]
fn architecture_signing_and_scope() {
    let (founder, f, alice, a) = founder_and_alice();
    let reg = Registry::build(&root(vec![founder, alice]));
    let node = |by: &str, paths: Vec<String>| ArchitectureEntry {
        kovan: EntryMeta {
            id: "arch-steam".into(),
            kind: "architecture".into(),
            origin: Some("human".into()),
            created: "2026-10-07T10:00:00+08:00".into(),
            modified: "2026-10-07T10:00:00+08:00".into(),
            target: None,
        },
        architecture: ArchitectureBody {
            by: by.into(),
            date: "2026-10-08".into(),
            signed_at: None,
            commit: SHA.into(),
            members: paths.iter().map(|p| crate::review::id::mint_fn_id(p, &h('a'), SHA)).collect(),
            member_paths: paths,
            upstream_tag: None,
            upstream: None,
            pattern: Some("concept:flash".into()),
            signature: None,
        },
        relations: vec![],
    };
    let mut n = node(ALICE, vec![F.into()]);
    a.sign_architecture(&mut n).unwrap();
    assert!(verify_architecture(&n, &reg).is_verified());
    let mut t = n.clone();
    t.architecture.members.push("fn:00000000000000ff".into());
    assert_eq!(unverified(verify_architecture(&t, &reg)), UnverifiedReason::BadSignature);
    let mut empty = node(ALICE, vec![]);
    a.sign_architecture(&mut empty).unwrap();
    assert_eq!(
        unverified(verify_architecture(&empty, &reg)),
        UnverifiedReason::OutsideScope { reviewer: ALICE.into(), path: String::new() }
    );
    let mut fe = node(FOUNDER, vec![]);
    f.sign_architecture(&mut fe).unwrap();
    assert!(verify_architecture(&fe, &reg).is_verified());
    assert!(matches!(a.sign_architecture(&mut node(FOUNDER, vec![])), Err(SignError::WrongReviewer { .. })));
}

/// The signer refuses statements that are not its own or are incomplete.
#[test]
fn sign_refusals() {
    let (_, f) = key(FOUNDER, "k1");
    let mut r = review_entry(F, ALICE, "2026-10-07");
    assert_eq!(
        f.sign_review(&mut r),
        Err(SignError::WrongReviewer { expected: ALICE.into(), signer: FOUNDER.into() })
    );
    let mut rv = Revocation { date: "2026-12-01".into(), compromised_from: None, by: ALICE.into(), signature: None };
    assert!(matches!(f.revoke(ALICE, &mut rv), Err(SignError::WrongReviewer { .. })));
    let (ak, _) = key(ALICE, "a1");
    let mut p = person(ALICE, Role::Reviewer, vec![ak]);
    assert_eq!(f.admit(&mut p), Err(SignError::Missing("admitted")));
    p.admitted = Some("soon".into());
    assert_eq!(f.admit(&mut p), Err(SignError::BadDate("soon".into())));
    p.admitted = Some("2026-10-07".into());
    p.keys.clear();
    assert_eq!(f.admit(&mut p), Err(SignError::Missing("a first key")));
}

/// Statements of different kinds never share bytes, so a signature over
/// one cannot be replayed as another; `is_date` accepts only `YYYY-MM-DD`.
#[test]
fn statements_are_domain_separated_and_dates_strict() {
    let (k, _) = key(FOUNDER, "k1");
    let mut p = person(ALICE, Role::Reviewer, vec![k.clone()]);
    p.admitted = Some("2026-10-07".into());
    let rv = Revocation { date: "2026-10-07".into(), compromised_from: None, by: FOUNDER.into(), signature: None };
    let all = [
        endorsement_bytes(ALICE, &k),
        admission_bytes(&p),
        revocation_bytes(ALICE, &rv),
        unretire_bytes(ALICE, &k, "2026-10-06", "2026-10-07"),
        key_event_bytes(ALICE, &k, &KeyEvent::unsigned(KeyEventKind::Revoked, "2026-10-07"), "", None),
        signed_bytes(&review_entry(F, ALICE, "2026-10-07")),
    ];
    let firsts: std::collections::BTreeSet<&[u8]> =
        all.iter().map(|b| b.split(|c| *c == b'\n').next().unwrap()).collect();
    assert_eq!(firsts.len(), all.len());
    p.keys.clear();
    assert!(String::from_utf8(admission_bytes(&p)).unwrap().contains("key=\"\" \"\""));
    assert!(is_date("2026-10-07"));
    for bad in ["2026-13-01", "2026-00-10", "2026-10-32", "26-10-07", "2026/10/07", "2026-1a-07"] {
        assert!(!is_date(bad), "{bad}");
    }
    assert_eq!(decode_public(&encode_b64(&[0u8; 31])), Err(CryptoError::BadLength { field: "public key", len: 31 }));
}

/// Every error's `Display` says something (the UI shows these).
#[test]
fn errors_display() {
    let p = std::path::PathBuf::from("/x");
    let ks = [
        KeystoreError::Io { path: p.clone(), message: "m".into() },
        KeystoreError::Parse { path: Some(p.clone()), message: "m".into() },
        KeystoreError::Parse { path: None, message: "m".into() },
        KeystoreError::Unsupported("u".into()),
        KeystoreError::BadField("f".into()),
        KeystoreError::Kdf("k".into()),
        KeystoreError::Field(crate::review::types::FieldError::BadReviewerId("x".into())),
        KeystoreError::BadKeyId("k".into()),
        KeystoreError::BadDate("d".into()),
        KeystoreError::EmptyPassphrase,
        KeystoreError::WrongPassphrase,
        KeystoreError::KeyMismatch,
        KeystoreError::Random("r".into()),
        KeystoreError::NoConfigDir,
        KeystoreError::AlreadyExists(p.clone()),
        KeystoreError::WrongFile { path: p },
    ];
    for e in ks {
        assert!(!e.to_string().is_empty());
    }
    let se = [
        SignError::WrongReviewer { expected: "a".into(), signer: "b".into() },
        SignError::Missing("x"),
        SignError::WrongKey,
        SignError::NotRetired,
        SignError::BadDate("d".into()),
        SignError::Lifecycle(LifecycleError::AlreadyRetired),
    ];
    for e in se {
        assert!(!e.to_string().is_empty());
    }
    for e in [
        LifecycleError::BadDate("d".into()),
        LifecycleError::AlreadyRetired,
        LifecycleError::NotRetired,
    ] {
        assert!(!e.to_string().is_empty());
    }
    for e in [
        CryptoError::BadBase64 { field: "f" },
        CryptoError::BadLength { field: "f", len: 1 },
        CryptoError::BadPublicKey,
        CryptoError::Mismatch,
    ] {
        assert!(!e.to_string().is_empty());
    }
}

/// The founder is named by `[code_review] founder` (maintainer, #762 Q1):
/// entry order does not matter, and a missing, unknown, non-maintainer or
/// admitted founder is a typed problem with nothing trusted.
#[test]
fn founder_is_explicit() {
    let (fk, f) = key(FOUNDER, "k1");
    let (ak, a) = key(ALICE, "a1");
    let founder = person(FOUNDER, Role::Maintainer, vec![fk.clone()]);
    let alice_m = person(ALICE, Role::Maintainer, vec![ak.clone()]);
    // Listed second, still the founder; the first entry is not.
    let reg = Registry::build(&root(vec![alice_m.clone(), founder.clone()]));
    assert_eq!(reg.founder, Ok(FOUNDER.to_string()));
    assert_eq!(reg.reviewer(FOUNDER).unwrap().admission, Admission::Founder);
    assert_eq!(
        reg.reviewer(ALICE).unwrap().admission,
        Admission::NotAdmitted(AdmissionProblem::Unadmitted)
    );
    assert!(verify_review(&signed(&f, F, "2026-10-07"), &reg).is_verified());
    assert!(!verify_review(&signed(&a, F, "2026-10-07"), &reg).is_verified());

    let mut admitted = founder.clone();
    admitted.admitted_by = Some(crate::review::root::KeySignature { key: "x".into(), signature: "AAAA".into() });
    let cases = [
        (root_with_founder(None, vec![founder.clone()]), FounderProblem::NotDeclared),
        (
            ReviewRoot { code_review: None, reviewers: vec![founder.clone()], deleted_crates: vec![] },
            FounderProblem::NotDeclared,
        ),
        (root_with_founder(Some("github:nobody"), vec![founder.clone()]), FounderProblem::Unknown("github:nobody".into())),
        (
            root_with_founder(Some(ALICE), vec![person(ALICE, Role::Reviewer, vec![ak])]),
            FounderProblem::NotMaintainer(ALICE.into()),
        ),
        (root(vec![admitted]), FounderProblem::HasAdmission(FOUNDER.into())),
        (root(vec![]), FounderProblem::Unknown(FOUNDER.into())),
    ];
    for (r, want) in cases {
        let reg = Registry::build(&r);
        assert_eq!(reg.founder, Err(want.clone()));
        assert!(reg.warnings().contains(&Warning::NoFounder(want)));
        assert!(reg.reviewers.iter().all(|r| !r.is_admitted()));
        assert!(reg.reviewers.iter().flat_map(|r| &r.keys).all(|k| !k.status.is_trusted()));
    }
    // The field round-trips through kovan_root.toml.
    let text = "[code_review]\nfounder = \"github:founder\"\n";
    let parsed = ReviewRoot::parse(text).unwrap();
    assert_eq!(parsed.code_review.unwrap().founder.as_deref(), Some(FOUNDER));
}
